 $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n///\r\n/// @alias margin()\r\n///\r\n@mixin m(\r\n  $a: null,\r\n  $x: null,\r\n  $y: null,\r\n  $t: null,\r\n  $r: null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include margin(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-axis()\r\n///\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center {\r\n  @include margin($x: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-center()\r\n///\r\n@mixin mx-auto {\r\n  @include margin-center;\r\n}\r\n\r\n@mixin margin-middle {\r\n  @include margin($y: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-middle()\r\n///\r\n@mixin my-auto {\r\n  @include margin-middle;\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n///\r\n/// @alias margin-all()\r\n///\r\n@mixin margin-square($margin) {\r\n  @include margin-all($margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin-all(auto);\r\n}\r\n\r\n///\r\n/// @alias margin-auto()\r\n///\r\n@mixin m-auto {\r\n  @include margin-auto;\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin-all(0);\r\n}\r\n\r\n///\r\n/// @alias margin-none()\r\n///\r\n@mixin m-none {\r\n  @include margin-none;\r\n}\r\n\r\n///\r\n/// @alias m-none()\r\n///\r\n@mixin m-0 {\r\n  @include m-none;\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-xy()\r\n///\r\n@mixin margin-axis($vertical: null, $horizontal: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-x($x: null) {\r\n  @include margin($x: $x);\r\n}\r\n\r\n///\r\n/// @alias margin-x()\r\n///\r\n@mixin mx($x: nul